import json
with open('issue-32.jsonl') as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line: continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(i, 'ERR', e)
            continue
        t = d.get('type')
        role = None
        msg = d.get('message')
        summary=''
        if msg and isinstance(msg, dict):
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                summary = content[:150]
            elif isinstance(content, list):
                parts=[]
                for c in content:
                    if isinstance(c, dict):
                        if c.get('type')=='text':
                            parts.append('TEXT:'+c.get('text','')[:150])
                        elif c.get('type')=='tool_use':
                            parts.append('TOOLUSE:'+c.get('name','')+' '+json.dumps(c.get('input',{}))[:150])
                        elif c.get('type')=='tool_result':
                            cont = c.get('content')
                            if isinstance(cont,list):
                                cont = ' '.join(str(x.get('text','')) for x in cont if isinstance(x,dict))
                            parts.append('TOOLRESULT:'+str(cont)[:150])
                summary='; '.join(parts)
        ts = d.get('timestamp','')
        print(f'{i} {ts} type={t} role={role} :: {summary}')
" > summary.txt
wc -l summary.txt

